import html,json
from pathlib import Path
from common import save,stamp,load

def plot(path,rows,xkey='iteration',title='Measured Q21 residuals'):
    pairs=[('relative_force_l2',1e-4,'Force / admission gate'),('acceleration_max',1e-3,'Maximum acceleration / gate')]
    text=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 500"><rect width="1200" height="500" fill="white"/><style>text{font:15px system-ui}</style>',f'<text x="45" y="28">{html.escape(title)}</text>']
    for i,(key,limit,label) in enumerate(pairs):
        x0=70+i*580;y0=80;w=480;h=300;xs=[r[xkey] for r in rows];ys=[r['metrics'][key]/limit for r in rows];lo=min(xs,default=0);hi=max(xs,default=1);top=max(1.2,max(ys,default=1)*1.05)
        points=' '.join(f'{x0+w*(x-lo)/max(hi-lo,1):.2f},{y0+h-h*y/top:.2f}' for x,y in zip(xs,ys))
        text += [f'<text x="{x0}" y="60">{label}</text>',f'<path d="M{x0},{y0}V{y0+h}H{x0+w}" fill="none" stroke="#334155"/>',f'<path d="M{x0},{y0+h-h/top}H{x0+w}" stroke="#15803d" stroke-dasharray="5 4"/>',f'<polyline points="{points}" fill="none" stroke="#2563eb" stroke-width="2"/>',f'<text x="{x0}" y="415">{html.escape(xkey)}: {lo} to {hi}; y: 0 to {top:.4g}</text>']
    text.append('<text x="70" y="470">Dashed line = measured gate. Optimizer steps are not physical time. Fits do not grant admission.</text></svg>')
    path.write_text('\n'.join(text)+'\n')

def assessment(folder,record):
    folder=Path(folder);folder.mkdir(parents=True,exist_ok=True);q=record['q21'];rows=[r for r in q['history'] if r['iteration']>=315];first,last=rows[0]['metrics'],rows[-1]['metrics']
    source=load(Path(__file__).parent/'SOURCE.json');gates=source['registered_gates'];lines=['# Completed Q21 tranche: scientific assessment','',json.dumps(stamp()),'', 'The numerical campaign completed, with 20 accepted updates from exact iteration315 to335. Its result and all failures were published in PR90. This additional assessment records the scientific interpretation and a separate literature-guided experiment plan.','', '| Quantity | Iteration315 | Iteration335 | Admission limit |','|---|---:|---:|---:|']
    for key,gate in [('relative_force_l2','force_limit'),('acceleration_max','acceleration_limit'),('tail_fraction','initial_tail_limit'),('guard_fraction','tail_guard_limit')]:lines.append(f'| {key} | {first[key]:.12g} | {last[key]:.12g} | {gates[gate]:.12g} |')
    lines += ['',f'Force improved by {100*(1-last["relative_force_l2"]/first["relative_force_l2"]):.3f}%; acceleration improved by {100*(1-last["acceleration_max"]/first["acceleration_max"]):.3f}%. Energy fell by {100*(1-last["energy"]/first["energy"]):.6f}%. These are improvements in an unresolved preparation, not a stability result.','', 'The lowest measured force occurs at330; the lowest maximum acceleration at334. No observation passes both stationarity gates. Endpoint335 is the declared common experimental parent; transient best observations are not silently substituted.','', 'Q2 remains an admitted instrument control. All20 new Q21 CPU/CUDA audits passed. Original gates, grid, box and conjugacy memory remained unchanged.','', 'Force fits at325 and330 had no model passing the25% chronological holdout threshold. They cannot support an ETA or extrapolated admission. Declining energy and improving median residuals do not imply monotone convergence.','', 'Q22 is deferred because the exact archived field was not recovered. The search charged68,695,595,358 bytes out of68,719,476,736 and reported incomplete coverage, including a nested-depth limit. This is a recovery limitation; historical positive native-cell findings remain recorded.','', 'The next campaign compares one factor at a time and keeps all measured failure gates visible. A nonstationary Hessian characterizes the local landscape; it does not certify physical instability. Physical-time motion and changed-potential/coupled models need separately qualified hypotheses.','']
    (folder/'ASSESSMENT.md').write_text('\n'.join(lines));save(folder/'ASSESSMENT.json',{'recorded_at':stamp(),'source':source,'final':q['final'],'initial':rows[0],'all_readiness_passes':sum(bool(r['gates']['all_readiness_gates']) for r in rows[1:]),'q22':record['q22'],'physical_time_steps':0})
    plot(folder/'measured-residuals.svg',rows)
    (folder/'ASSESSMENT.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Q21 completed tranche assessment</title><style>body{font:16px/1.55 system-ui;max-width:1150px;margin:30px auto;padding:20px}img{max-width:100%}pre{white-space:pre-wrap}</style><h1>Q21 completed tranche assessment</h1><img src="measured-residuals.svg" alt="Measured force and acceleration against gates"><pre>'+html.escape('\n'.join(lines))+'</pre><p><a href="ASSESSMENT.json">Machine-readable assessment</a> · <a href="../LITERATURE.md">Literature and applicability</a></p></html>\n')

def campaign(out,records,phase,deferred,complete=False):
    rows=[];csv=['arm,status,accepted_steps,charged_attempts,force,acceleration,tail,guard,all_readiness_gates']
    for a in records:
        m=a['final']['metrics'];ga=a['final']['gates'];aid=a['arm']['id'];plot(out/'arms'/aid/'history.svg',a['history'],'step',aid)
        vals=[aid,a['status'],a['accepted_steps'],a['charged_attempts'],m['relative_force_l2'],m['acceleration_max'],m['tail_fraction'],m['guard_fraction'],ga['all_readiness_gates']]
        csv.append(','.join(map(str,vals)));rows.append('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in vals)+'</tr>')
    (out/'screening.csv').write_text('\n'.join(csv)+'\n')
    text='<!doctype html><html lang="en"><meta charset="utf-8"><title>Literature-guided stability diagnosis</title><style>body{font:15px/1.5 system-ui;max-width:1400px;margin:25px auto;padding:20px}table{border-collapse:collapse}td,th{padding:7px;border:1px solid #cbd5e1}pre{white-space:pre-wrap}img{max-width:100%}</style><h1>Literature-guided stability diagnosis</h1><p>These are controlled preparations under the unchanged neutral SF action. Numerical readiness, local curvature, motion stability and electron interpretation remain separate claims.</p><p><a href="record.json">Full measured record</a> · <a href="handover/assessment/ASSESSMENT.html">Prior scientific assessment</a> · <a href="handover/LITERATURE.md">Literature applicability</a> · <a href="OPTIONS.json">Option dispositions</a> · <a href="RELATIONSHIPS.json">Matched-step dependencies and fits</a> · <a href="MOTION.json">Conditional motion disposition</a></p><p>Phase: '+html.escape(str(phase))+'</p><table><tr>'+''.join('<th>'+x+'</th>' for x in csv[0].split(','))+'</tr>'+''.join(rows)+'</table>'
    for a in records:
        aid=a['arm']['id'];text+='<details><summary>'+html.escape(aid)+'</summary><img src="arms/'+aid+'/history.svg" alt="Measured residual history"><pre>'+html.escape(json.dumps({'initialization':a['initialization'],'reason':a['reason'],'best_retained':a.get('best'),'final_geometry':a.get('geometry')},indent=2))+'</pre></details>'
    text+='<h2>Explicit limitations and deferrals</h2><pre>'+html.escape(json.dumps(deferred,indent=2))+'</pre><p>Completed: '+str(complete)+'. Retained full field checkpoints stay local; compact evidence carries their hashes. Positive preparation screens are not long-time or continuum stability proofs.</p></html>\n'
    (out/'REPORT.html').write_text(text)
